{
  "criteria": [
    {
      "id": "C1",
      "level": "Adequate",
      "mark": 6,
      "evidence": [
        {
          "where": "Introduction",
          "quote": "The spacecraft is intended to image and send data to ground stations for collation and analysis."
        },
        {
          "where": "Introduction",
          "quote": "Thus, only one satellite is required."
        }
      ],
      "reasoning": "The mission purpose and Australian conservation rationale are explained, and a single spacecraft is justified in terms of coverage needs, simplicity and cost. The operator and customer groups are not clearly identified, and the rationale and user discussion are not supported consistently by formal literature citations."
    },
    {
      "id": "C2",
      "level": "Adequate",
      "mark": 5,
      "evidence": [
        {
          "where": "Launch",
          "quote": "The proposed satellite will thus use the Vega E rocket as a launch vehicle"
        },
        {
          "where": "Orbit",
          "quote": "an altitude of 600km requires a mean inclination of $ 87.7924^{\\circ} $"
        },
        {
          "where": "Ground Control & Communications",
          "quote": "An average contact duration of almost twenty minutes was achieved"
        },
        {
          "where": "Mission Duration & EOL",
          "quote": "A span of five years is a sound estimate of the useful lifespan"
        }
      ],
      "reasoning": "The report covers launch, orbit, STK access analysis, ground station, duration and disposal, with useful simulation outputs. However, the stated inclination is inconsistent with a 600 km sun-synchronous orbit: it should be about 97.8°, not 87.79°. The launch-site latitude is also wrong, launch timing is inconsistent, and the maneuver/EOL discussion lacks a quantified disposal plan. No software files are supplied."
    },
    {
      "id": "C3",
      "level": "Adequate",
      "mark": 5,
      "evidence": [
        {
          "where": "Conclusion",
          "quote": "After analysis of each mission segment, a fully described satellite configuration has been constructed."
        }
      ],
      "reasoning": "The conclusion summarizes the proposed launcher, orbit and ground station and notes launch uncertainty. It is relevant but mostly restates design choices, does not assess key limitations or uncertainties in the evidence, and repeats the incorrect characterization of the orbit as suitable for consistent illumination."
    },
    {
      "id": "C4",
      "level": "Adequate",
      "mark": 4,
      "evidence": [
        {
          "where": "Executive Summary",
          "quote": "This report outlines the intended designs and procedures involved in the construction of a Earth observation satellite"
        },
        {
          "where": "Bibliography",
          "quote": "[6] https://en.wikipedia.org/wiki/2021_in_spaceflight. [Online]."
        },
        {
          "where": "Mission Duration & EOL",
          "quote": "utilising a large surface area to ‘ and is suitable for low-earth orbit altitudes"
        }
      ],
      "reasoning": "The report has a recognizable structure, executive summary, figures, tables and bibliography. However, grammar and editing problems remain, the EOL sentence is incomplete, and figure/table presentation and citations are inconsistent. The bibliography is mostly bare URLs and includes Wikipedia, which the task explicitly disallows. These issues reduce professionalism and traceability."
    }
  ],
  "requirements": [
    {
      "id": "R1",
      "met": "yes",
      "where": "Introduction"
    },
    {
      "id": "R2",
      "met": "yes",
      "where": "Introduction"
    },
    {
      "id": "R3",
      "met": "partial",
      "where": "Introduction"
    },
    {
      "id": "R4",
      "met": "partial",
      "where": "Launch"
    },
    {
      "id": "R5",
      "met": "partial",
      "where": "Orbit"
    },
    {
      "id": "R6",
      "met": "partial",
      "where": "Orbit"
    },
    {
      "id": "R7",
      "met": "yes",
      "where": "Ground Control & Communications"
    },
    {
      "id": "R8",
      "met": "partial",
      "where": "Mission Duration & EOL"
    },
    {
      "id": "R9",
      "met": "yes",
      "where": "Ground Control & Communications"
    },
    {
      "id": "R10",
      "met": "partial",
